const input = $input.first().json;
const chatId = input.chatId || '';
const fromUser = input.fromUser || '';
const rawUrl = input.driveUrl || input.rawText || '';

let fileId = '';
const m1 = rawUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
const m2 = rawUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
if (m1) fileId = m1[1];
else if (m2) fileId = m2[1];

if (!fileId) throw new Error('Impossible d\'extraire le fileId du lien: ' + rawUrl);

return [{ json: { chatId, fromUser, fileId, source: 'LIEN_DRIVE' } }];

const input = $('🔗 Trigger — Commander').first().json;
const chatId = input.chatId || $env.GED_TELEGRAM_CHAT_ID || '';
const fromUser = input.fromUser || 'Utilisateur';

const rows = $input.all().map(i => i.json);
const file = rows.filter(r =>
  ['VALIDER','VENTILER'].includes((r.Action_Requise || '').toUpperCase())
  && r.File_Id
);

if (file.length === 0) {
  return [{ json: {
    chatId, fromUser,
    vide: true,
    msg: '✅ <b>Aucun document en attente de validation.</b>\n\nTous les documents ont été classés avec confiance haute.\nPour corriger un doc spécifique, colle son lien Drive dans ce chat.'
  }}];
}

const doc = file[0];
return [{ json: {
  chatId, fromUser,
  vide: false,
  fileId: doc.File_Id,
  fileName: doc.File_Name || '(sans nom)',
  natureActuelle: doc.Nature_Finale || '?',
  confiance: doc.Confiance || '?',
  raisonDoute: doc.Raison_Doute || '',
  lienDrive: doc.Lien_Drive || '',
  source: 'RECLASS_BOT',
  fileEnAttente: file.length,
  rowIndex: rows.findIndex(r => r.File_Id === doc.File_Id) + 2
} }];

const fromLien = (() => { try { return $('🔗 Extraire FileId du Lien').first().json; } catch(e) { return null; } })();
const fromFile = (() => { try { const d = $('🗂️ Construire File Reclass').first().json; return d.vide ? null : d; } catch(e) { return null; } })();

const d = fromLien || fromFile;
if (!d || !d.fileId) throw new Error('Aucun fileId disponible');

return [{ json: {
  chatId: d.chatId,
  fromUser: d.fromUser,
  fileId: d.fileId,
  fileName: d.fileName || '',
  natureActuelle: d.natureActuelle || '',
  confiance: d.confiance || '',
  raisonDoute: d.raisonDoute || '',
  lienDrive: d.lienDrive || 'https://drive.google.com/file/d/' + d.fileId + '/view',
  source: d.source || 'LIEN_DRIVE',
  fileEnAttente: d.fileEnAttente || 0,
  rowIndex: d.rowIndex || 0
} }];

const ctx = $('⚙️ Fusionner Contexte').first().json;
const fileId = ctx.fileId;

function findRow(resp, sheetName) {
  const rows = resp?.values || [];
  if (rows.length < 2) return null;
  const headers = rows[0];
  const fileIdCol = headers.findIndex(h => h === 'File_Id');
  if (fileIdCol === -1) return null;
  for (let i = 1; i < rows.length; i++) {
    if (rows[i][fileIdCol] === fileId) {
      const rowObj = {};
      headers.forEach((h, idx) => { rowObj[h] = rows[i][idx] || ''; });
      return { rowObj, rowIndex: i, sheetName, headers, rawRow: rows[i] };
    }
  }
  return null;
}

let found = null;
try { const r = $('🔍 Sheets — _REVUE_BATCH').first().json; found = findRow(r, '_REVUE_BATCH'); } catch(e) {}
if (!found) try { const r = $('🔍 Sheets — Journal_GED').first().json; found = findRow(r, 'Journal_GED'); } catch(e) {}
if (!found) try { const r = $('🔍 Sheets — Journal_Comptable').first().json; found = findRow(r, 'Journal_Comptable'); } catch(e) {}

let driveParentId = '';
let dossierActuelNom = '';
let physicalNature = '';

// ── Drive API = source de vérité absolue pour nom et lien ─────────────────
let driveFile;
try {
  driveFile = $('📡 Drive — Get File Info').first().json;
  driveParentId = driveFile?.parents?.[0] || '';
} catch (err) {
  if (!found) throw new Error(`Impossible de récupérer les infos du fichier Drive: ${err.message}`);
}

// Toujours utiliser Drive API pour File_Name et Lien_Drive — jamais le journal
const realFileName = driveFile?.name || (found?.rowObj?.File_Name) || 'Document sans nom';
const realLienDrive = driveFile?.webViewLink || `https://drive.google.com/file/d/${fileId}/view`;

try {
  const parentFolder = $('📂 Drive — Résoudre Dossier Actuel').first().json;
  dossierActuelNom = parentFolder.name || '';
  const n = dossierActuelNom.toLowerCase();
  if (n.includes('impôt') || n.includes('fiscal') || n.includes('taxe')) physicalNature = 'FISCAL';
  else if (n.includes('compta')) physicalNature = 'COMPTABLE';
  else if (n.includes('_ged_archive') || n.includes('admin')) physicalNature = 'ADMIN';
  else if (n.includes('doublon') || n.includes('_doublons')) physicalNature = 'DOUBLON';
  else if (n.includes('ged')) physicalNature = 'GED';
} catch(e) {}

if (!found) {
  const rowObj = {
    File_Id: fileId,
    File_Name: realFileName,
    Lien_Drive: realLienDrive,
    Date_Traitement: new Date().toISOString(),
    Statut: 'NON_RÉFÉRENCÉ',
    Nature_Finale: physicalNature || 'INCONNU',
  };
  found = { rowObj, rowIndex: 0, sheetName: 'NONE', headers: Object.keys(rowObj), rawRow: Object.values(rowObj) };
}

// Écraser File_Name et Lien_Drive dans foundRow avec les données Drive réelles
found.rowObj.File_Name = realFileName;
found.rowObj.Lien_Drive = realLienDrive;

return [{
  json: {
    ...ctx,
    foundRow: found.rowObj,
    sourceSheet: found.sheetName,
    sourceRowIndex: found.rowIndex,
    sourceHeaders: found.headers,
    sourceRawRow: found.rawRow,
    driveParentId,
    dossierActuelNom,
    physicalNature
  }
}];

const ctx = $('🧩 Agréger Résultats').first().json;
const row = ctx.foundRow || {};

let natureActuelle = ctx.physicalNature || row.Nature_Finale || '';
if (!natureActuelle) {
  if (ctx.sourceSheet === 'Journal_Comptable') natureActuelle = 'COMPTABLE';
  else if (ctx.sourceSheet === 'Journal_GED')  natureActuelle = 'GED';
  else                                          natureActuelle = 'INCONNU';
}

const confiance   = (row.Confiance || '?').toUpperCase();
const raisonDoute = row.Raison_Doute || '';
const fileName    = row.File_Name || ctx.fileName || '(sans nom)';
const lienDrive   = row.Lien_Drive || ctx.lienDrive || `https://drive.google.com/file/d/${ctx.fileId}/view`;
const rowIndex    = ctx.sourceRowIndex || 0;
const dossierNom  = ctx.dossierActuelNom || '';

const badgeConf = confiance === 'HAUTE'  ? '🟢 HAUTE'
               : confiance === 'MOYENNE' ? '🟡 MOYENNE'
               : confiance === 'BASSE'   ? '🔴 BASSE'
               : '⚫ ?';

const icones = { GED:'🗄️', FISCAL:'📊', COMPTABLE:'🧾', ADMIN:'🗃️', DOUBLON:'♻️', INCONNU:'❓' };
const ico = icones[natureActuelle] || '📄';

// ── Message fiche ─────────────────────────────────────────────────
const lines = [
  '<b>🔁 Reclassification</b>',
  '',
  `📄 <b>${fileName}</b>`,
  `${ico} Classé actuellement : <b>${natureActuelle}</b>`,
  dossierNom  ? `🗂️ Dossier Drive : <i>${dossierNom}</i>` : '',
  `🤖 Confiance IA : ${badgeConf}`,
  raisonDoute ? `💬 Note IA : <i>${raisonDoute}</i>` : '',
  `🔗 <a href='${lienDrive}'>Ouvrir dans Drive</a>`,
  '',
  natureActuelle !== 'INCONNU' ? `💡 Suggestion IA : <b>${ico} ${natureActuelle}</b>` : '',
  '👇 <b>Choisir la bonne catégorie :</b>'
].filter(Boolean);
const msgFiche = lines.join('\n');

// ── Boutons : ordre dynamique selon nature actuelle ───────────────
const allCat = [
  { nature:'GED',       text:'🗄️ Archiver (GED)',      cb:'G' },
  { nature:'FISCAL',    text:'📊 Impôts / Fiscal',      cb:'F' },
  { nature:'COMPTABLE', text:'🧾 Facture / Comptable',  cb:'C' },
  { nature:'ADMIN',     text:'🗃️ Admin / Identité',     cb:'A' },
  { nature:'DOUBLON',   text:'♻️ Doublon',              cb:'D' },
];

// Remonter la nature actuelle en 1re position
const idx = allCat.findIndex(b => b.nature === natureActuelle);
if (idx > 0) { const [cur] = allCat.splice(idx, 1); allCat.unshift(cur); }

// Construire le inline_keyboard Telegram (paires de boutons par rangée)
const makeBtn = (text, cb) => ({
  text,
  callback_data: `${ctx.fileId}|${cb}|${rowIndex}`
});

const keyboard = [];
for (let i = 0; i < allCat.length; i += 2) {
  const pair = allCat.slice(i, i + 2).map(b => makeBtn(b.text, b.cb));
  keyboard.push(pair);
}
// Rangée actions
keyboard.push([
  makeBtn('✏️ Corriger journal', 'J'),
  makeBtn('⏩ Passer',           'S'),
]);
// Rangée contrôle
keyboard.push([
  makeBtn('🛑 Terminer session', 'T'),
]);

// Sérialiser en JSON string pour additionalFields.reply_markup
const replyMarkupStr = JSON.stringify({ inline_keyboard: keyboard });

return [{ json: {
  ...ctx,
  fileName, natureActuelle, confiance, raisonDoute, lienDrive, rowIndex,
  msgFiche,
  replyMarkupStr   // ← JSON string pour Telegram API
} }];

const input = $input.first().json;

if (input.command === 'CALLBACK') {
  const data = input.callbackData || '';
  const parts = data.split('|');
  const fileId = parts[0] || '';
  const natureAbrev = parts[1] || '';
  const rowIndex = parseInt(parts[2] || '0');
  const mapNature = { 'G':'GED', 'F':'FISCAL', 'C':'COMPTABLE', 'A':'ADMIN', 'D':'DOUBLON', 'J':'CORRECT', 'S':'SKIP', 'T':'STOP' };
  const nouvelleNature = mapNature[natureAbrev] || natureAbrev;
  return [{ json: {
    chatId: String(input.chatId || ''),
    fromUser: input.fromUser || 'Utilisateur',
    fileId,
    nouvelleNature,
    rowIndex,
    source: 'LIEN_DRIVE',
    sourceSheet: '',
    callbackQueryId: input.callbackQueryId || '',
    messageId: String(input.messageId || ''),
    isSkip: nouvelleNature === 'SKIP',
    isStop: nouvelleNature === 'STOP',
    isCorrectJournalOnly: nouvelleNature === 'CORRECT'
  } }];
}

const cb = input.callback_query;
const data = cb?.data || '';
const parts = data.split('|');
const fileId = parts[0] || '';
const natureAbrev = parts[1] || '';
const rowIndex = parseInt(parts[2] || '0');
const mapNature = { 'G':'GED', 'F':'FISCAL', 'C':'COMPTABLE', 'A':'ADMIN', 'D':'DOUBLON', 'J':'CORRECT', 'S':'SKIP', 'T':'STOP' };
const nouvelleNature = mapNature[natureAbrev] || natureAbrev;

return [{ json: {
  chatId: String(cb?.message?.chat?.id || ''),
  fromUser: cb?.from?.first_name || 'Utilisateur',
  fileId,
  nouvelleNature,
  rowIndex,
  source: 'LIEN_DRIVE',
  sourceSheet: '',
  callbackQueryId: cb?.id || '',
  messageId: String(cb?.message?.message_id || ''),
  isSkip: nouvelleNature === 'SKIP',
  isStop: nouvelleNature === 'STOP',
  isCorrectJournalOnly: nouvelleNature === 'CORRECT'
} }];

const ctx = $('🧩 Agréger Résultats Callback').first().json;
const sourceSheet = ctx.sourceSheet;
const rowIndex    = ctx.sourceRowIndex ?? ctx.rowIndex;
const headers     = ctx.sourceHeaders || [];

// Pas de sheet source → skip silencieux
if (!sourceSheet || sourceSheet === 'NONE' || !rowIndex) {
  return [{ json: { ...ctx, skipMark: true, updateRange: '',
    _markNote: 'Aucune sheet source — skip mark' } }];
}

// Chercher la colonne 'Statut' dans les headers réels
const statutColIdx = headers.findIndex(h => h === 'Statut');

if (statutColIdx === -1) {
  // Colonne Statut absente → skip, traçabilité via Logger _CORRECTIONS
  return [{ json: { ...ctx, skipMark: true, updateRange: '',
    _markNote: 'Colonne Statut absente de ' + sourceSheet
              + ' (' + headers.length + ' cols) — skip' } }];
}

// Index 0-based → lettre(s) Sheets (A, B … Z, AA, AB …)
function colLetter(idx) {
  let r = '', n = idx + 1;
  while (n > 0) { n--; r = String.fromCharCode(65 + (n % 26)) + r; n = Math.floor(n / 26); }
  return r;
}

const col = colLetter(statutColIdx);
const updateRange = sourceSheet + '!' + col + rowIndex + ':' + col + rowIndex;
return [{ json: { ...ctx, skipMark: false, updateRange,
  _markNote: 'Statut col=' + col + ' idx=' + statutColIdx + ' row=' + rowIndex } }];

const inputData = $input.first().json;
const cb = (() => { try { return $('🔍 Parser Callback').first().json; } catch(e) { return null; } })();
const agg = (() => {
  try { return $('🧩 Agréger Résultats Callback').first().json; } catch(e1) {
    try { return $('🧩 Agréger Résultats').first().json; } catch(e2) { return null; }
  }
})();

const chatId = cb?.chatId || inputData.chatId || '';
const fromUser = cb?.fromUser || inputData.fromUser || 'Utilisateur';
const nouvelleNature = cb?.nouvelleNature || inputData.nouvelleNature || '';
const fileId = cb?.fileId || inputData.fileId || '';
const callbackQueryId = cb?.callbackQueryId || inputData.callbackQueryId || '';
const isSkip = cb?.isSkip ?? inputData.isSkip ?? false;
const isStop = cb?.isStop ?? inputData.isStop ?? false;
const isCorrectJournalOnly = cb?.isCorrectJournalOnly ?? inputData.isCorrectJournalOnly ?? false;

// Lire sourceSheet et rowIndex depuis Agréger Résultats Callback (priorité) puis cb
const sourceSheet = agg?.sourceSheet || cb?.sourceSheet || inputData.sourceSheet || 'NONE';
const rowIndex = agg?.rowIndex ?? agg?.sourceRowIndex ?? cb?.rowIndex ?? inputData.rowIndex ?? 0;

// Est_Fiscal et Famille_Document calculés par Agréger Résultats Callback
const Est_Fiscal = agg?.Est_Fiscal || (nouvelleNature === 'FISCAL' ? 'TRUE' : 'FALSE');
const Famille_Document = agg?.Famille_Document || '';

let rowData = {};
if (agg && agg.foundRow) {
  rowData = {
    ...agg.foundRow,
    Est_Fiscal,
    Famille_Document,
    Annee_Fiscale: agg.foundRow.Annee_Fiscale || String(new Date().getFullYear())
  };
} else {
  rowData = {
    File_Name: inputData.fileName || '',
    Lien_Drive: inputData.lienDrive || `https://drive.google.com/file/d/${fileId}/view`,
    Date: '', Confiance: '', Raison_Doute: '', Nature_Finale: '',
    Est_Fiscal, Famille_Document
  };
}

let annee = new Date().getFullYear();
try { if (rowData.Date) annee = new Date(rowData.Date).getFullYear(); } catch(e) {}

let parentFolderId = null;
let targetFolderName = null;

if (isCorrectJournalOnly) {
  const physicalNature = agg?.physicalNature || 'INCONNU';
  const correctJournal = (physicalNature === 'FISCAL' || physicalNature === 'COMPTABLE')
    ? 'Journal_Comptable'
    : (physicalNature === 'GED' || physicalNature === 'ADMIN')
    ? 'Journal_GED' : 'NONE';
  return [{
    json: {
      chatId, fromUser, fileId, sourceSheet, rowIndex,
      nouvelleNature: physicalNature, callbackQueryId, isSkip, isStop,
      isCorrectJournalOnly: true, physicalNature, correctJournal,
      annee, parentFolderId: null, targetFolderName: null, oldParentId: '',
      rowData, Est_Fiscal, Famille_Document,
      fileName: rowData.File_Name || inputData.fileName || '',
      natureActuelle: physicalNature,
      lienDrive: rowData.Lien_Drive || `https://drive.google.com/file/d/${fileId}/view`,
      source: inputData.source || 'LIEN_DRIVE'
    }
  }];
}

if (nouvelleNature === 'GED') {
  parentFolderId = $env.GED_GED_PARENT_ID || $env.GED_ADMIN_PARENT_ID || null;
  targetFolderName = `GED ${annee}`;
} else if (nouvelleNature === 'FISCAL') {
  parentFolderId = $env.GED_IMPOTS_PARENT_ID || null;
  targetFolderName = `Impôts ${annee}`;
} else if (nouvelleNature === 'COMPTABLE') {
  parentFolderId = $env.GED_COMPTA_PARENT_ID || null;
  targetFolderName = `Comptabilité ${annee}`;
} else if (nouvelleNature === 'ADMIN') {
  parentFolderId = $env.GED_ADMIN_PARENT_ID || null;
  targetFolderName = `_GED_ARCHIVE`;
} else if (nouvelleNature === 'DOUBLON') {
  parentFolderId = $env.GED_DOUBLONS_FOLDER_ID || null;
  targetFolderName = '_DOUBLONS';
} else {
  parentFolderId = $env.GED_ARCHIVE_FOLDER_ID || null;
  targetFolderName = '_GED_ARCHIVE';
}

if (!parentFolderId) {
  throw new Error(`Variable d'environnement manquante pour nouvelleNature=${nouvelleNature}`);
}

let oldParentId = '';
try { oldParentId = $('📡 Drive — Get File Info').first().json?.parents?.[0] || ''; } catch(e) {}

return [{
  json: {
    chatId, fromUser, fileId, sourceSheet, rowIndex,
    nouvelleNature, callbackQueryId, isSkip, isStop,
    isCorrectJournalOnly: false,
    annee, parentFolderId, targetFolderName, oldParentId,
    rowData, Est_Fiscal, Famille_Document,
    fileName: rowData.File_Name || inputData.fileName || '',
    natureActuelle: rowData.Nature_Finale || inputData.natureActuelle || '',
    lienDrive: rowData.Lien_Drive || `https://drive.google.com/file/d/${fileId}/view`,
    source: inputData.source || 'LIEN_DRIVE'
  }
}];

const ctx = $('⚙️ Calculer Destination').first().json;

let newFolderId = null;

// 1. Essayer de récupérer depuis la création
try {
  const createFolderResult = $('📁 Créer Dossier Annuel Reclass').first().json;
  if (createFolderResult.id) {
    newFolderId = createFolderResult.id;
  }
} catch (e) { /* Ignorer et passer à l'étape suivante */ }

// 2. Essayer de récupérer depuis la recherche si non trouvé
if (!newFolderId) {
  try {
    const searchResult = $('🔍 Reclass — Search Dossier Annuel').first().json;
    if (searchResult.files?.length > 0 && searchResult.files[0].id) {
      newFolderId = searchResult.files[0].id;
    }
  } catch (e) { /* Ignorer pour le contrôle final */ }
}

// 3. Vérifier si on a un ID valide
if (!newFolderId) {
  throw new Error("Impossible de récupérer l'ID du dossier annuel : ni la création ni la recherche n'ont fourni d'ID.");
}

return [{
  json: {
    ...ctx,
    newFolderId
  }
}];

const d = $('⚙️ Calculer Destination').first().json;

const icones = {
  FISCAL:    '📊', COMPTABLE: '🧾', GED:   '🗄️',
  DOUBLON:   '♻️', ADMIN:     '🗃️', INCONNU: '❓'
};
const icoNew = icones[d.nouvelleNature] || '📄';
const icoOld = icones[d.natureActuelle] || '📄';
const fileName = d.rowData?.File_Name || d.fileName || 'Document';

let msg;

if (d.isCorrectJournalOnly) {
  msg = [
    `✏️ <b>Journal corrigé</b>`,
    '',
    `📄 ${fileName}`,
    `📋 Journal mis à jour : <b>${d.correctJournal || 'Journal_GED'}</b>`,
    `📁 Fichier Drive inchangé — reste dans <i>${d.dossierActuelNom || 'son dossier actuel'}</i>`,
    '',
    '<i>Colle un autre lien pour continuer.</i>'
  ].join('\n');

} else if (d.nouvelleNature === 'DOUBLON') {
  msg = [
    `♻️ <b>Doublon archivé</b>`,
    '',
    `📄 ${fileName}`,
    `📁 Déplacé → <b>_DOUBLONS</b>`,
    `📋 Tracé dans Journal_GED`,
    '',
    '<i>Colle un autre lien pour continuer.</i>'
  ].join('\n');

} else {
  msg = [
    `✅ <b>Reclassifié avec succès</b>`,
    '',
    `📄 ${fileName}`,
    `${icoOld} <i>${d.natureActuelle || '?'}</i>  →  ${icoNew} <b>${d.nouvelleNature}</b>`,
    `📁 Déplacé vers <b>${d.targetFolderName || d.nouvelleNature}</b>`,
    '',
    '<i>Colle un autre lien pour continuer.</i>'
  ].join('\n');
}

return [{ json: { chatId: d.chatId, msg } }];

const ctx = $('⚙️ Calculer Destination').first().json;
const searchResult = $input.first().json;

const newFolderId = searchResult?.files?.[0]?.id || null;

if (!newFolderId) {
  throw new Error("Impossible de récupérer l'ID du dossier annuel depuis la recherche existante.");
}

return [{
  json: {
    ...ctx,
    newFolderId
  }
}];

const ctx = $('🔍 Parser Callback').first().json;
const fileId = ctx.fileId;
const nouvelleNature = ctx.nouvelleNature || '';

function findRow(resp, sheetName) {
  const rows = resp?.values || [];
  if (rows.length < 2) return null;
  const headers = rows[0];
  const fileIdCol = headers.findIndex(h => h === 'File_Id');
  const driveLinkCol = headers.findIndex(h => h === 'Lien_Drive');
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    let isMatch = false;
    if (fileIdCol !== -1 && row[fileIdCol] === fileId) {
      isMatch = true;
    } else if (driveLinkCol !== -1) {
      const driveLink = row[driveLinkCol] || '';
      const match = driveLink.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
      if (match && match[1] === fileId) isMatch = true;
    }
    if (isMatch) {
      const rowObj = {};
      headers.forEach((h, idx) => { rowObj[h] = row[idx] || ''; });
      return { rowObj, rowIndex: i + 1, sheetName };
    }
  }
  return null;
}

let found = null;
try { const r = $('🔍 CB — _REVUE_BATCH').first().json; found = findRow(r, '_REVUE_BATCH'); } catch(e) {}
if (!found) try { const r = $('🔍 CB — Journal_GED').first().json; found = findRow(r, 'Journal_GED'); } catch(e) {}
if (!found) try { const r = $('🔍 CB — Journal_Comptable').first().json; found = findRow(r, 'Journal_Comptable'); } catch(e) {}

if (!found) {
  throw new Error(`Document File_Id=${fileId} introuvable dans les 3 sources.`);
}

// Map sheetId numériques (statique — GED_Registre_Grl)
const SHEET_IDS = {
  'Journal_Comptable': 334720485,
  'Journal_GED': 1481094461,
  '_REVUE_BATCH': 1248636427
};

const isFiscal = ['FISCAL', 'COMPTABLE_FISCAL', 'MIXTE'].includes(nouvelleNature);
const familleMap = {
  'FISCAL': 'FISCAL', 'COMPTABLE_FISCAL': 'COMPTABLE',
  'COMPTABLE': 'COMPTABLE', 'GED': 'GED', 'ADMIN': 'ADMIN', 'MIXTE': 'FISCAL'
};
const famille = familleMap[nouvelleNature] || found.rowObj['Famille_Document'] || '';

return [{
  json: {
    ...ctx,
    foundRow: found.rowObj,
    sourceSheet: found.sheetName,
    sourceSheetId: SHEET_IDS[found.sheetName] ?? null,
    sourceRowIndex: found.rowIndex,
    rowIndex: found.rowIndex,
    sourceHeaders: found.headers || [],
    nouvelleNature,
    Est_Fiscal: isFiscal ? 'TRUE' : 'FALSE',
    Famille_Document: famille
  }
}];
